def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    op = [h[1] for h in history]
    op_c = sum(1 for a in op if a == 'C')
    last_me = history[-1][0]
    last_op = op[-1]
    if op_c == 0:
        return 'D'
    if op_c >= n - max(1, n // 10):
        if last_op == 'D':
            return 'D'
        return 'C'
    if op_c <= n // 3:
        if last_me == 'D' and last_op == 'D':
            return 'C'
        if last_op == 'D':
            return 'D'
        return 'C'
    if last_op == 'D':
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    return 'C'
